<form action="/welcome/claim" method="post" class="welcome-email-form" data-welcome-claim><?= csrf_field() ?><label>Email address<input type="email" name="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"></label><button class="button full" type="submit">Send verification email</button><p role="status" aria-live="polite" data-claim-status></p><div class="welcome-code-result" data-claim-result hidden><label>Your private code<input type="text" readonly data-claim-code aria-label="Your welcome discount code"></label><button class="button outline" type="button" data-copy-code>Copy Code</button><p data-claim-expiry></p><p>At checkout, enter this code and click Apply. Use the same email address you entered here.</p><a class="text-link" href="/checkout">Go to checkout</a></div></form>
